/**
 * 时光代理人 (Shiguang Dailiren) skin — ported from the standalone
 * dsh-skin-link-click plugin into the dsh-web-ui skin collection.
 *
 * apply() owns the whole surface and retracts it on dispose (the
 * ThemePresenter retraction discipline: the plugin only ever removes what it
 * wrote):
 *  - the `data-dsh-link-click` body attribute the stylesheet is scoped on,
 *  - the misty mauve × slate frosted-glass theme-token remap (theme service,
 *    optional; palette measured from the embedded wallpaper),
 *  - the wallpaper backdrop CSS variables (--skn-*) on <html>,
 *  - the 🖌 header toggle + right-panel control surface (slots service,
 *    optional; skipped when the services are absent so the skin degrades to
 *    a pure backdrop),
 *  - the custom-wallpaper upload (localStorage-backed, auto-compressed).
 * The scoped stylesheet rides the bundle's CSS-modules auto-inject (style tag
 * owned by the loader, removed on entry dispose).
 */
import type { Context } from '@deepseek-ai/cordis'
import { createElement, useEffect, useState } from 'react'
import { WALLPAPER } from './art.ts'
import './link-click.module.css'

const WALLPAPER_KEY = 'dsh-skin-link-click:wallpaper'
const STATE_KEY = 'dsh-skin-link-click:state'
const DEFAULTS = { bg: 35, layer1: 74, sidebar: 35, pos: 50, zoom: 100, genui: 65 } as const
type StateKey = keyof typeof DEFAULTS
type State = Record<StateKey, number>

/** theme.overrideTokens — the dsh theme service surface used by the skin. */
interface ThemeService {
  overrideTokens(id: string, tokens: Record<string, { light: string; dark: string }>): void
}

/** Minimal slots surface for the header toggle + right-panel registration. */
interface SlotsService {
  inject(name: string, register: () => unknown): () => void
  register(definition: Record<string, unknown>, render: (props: Record<string, unknown>) => unknown): unknown
}

/** Layout service that opens/closes the right details column. */
interface LayoutService {
  openDetails(): void
  closeDetails(): void
}

/* ------------------------------------------------------------------ */
/* State & persistence                                                  */
/* ------------------------------------------------------------------ */

function loadInitial(): { wallpaper?: string; state: State } {
  let wallpaper: string | undefined
  try { wallpaper = localStorage.getItem(WALLPAPER_KEY) || undefined } catch { /* noop */ }
  let saved: Partial<State> | null = null
  try {
    const raw = localStorage.getItem(STATE_KEY)
    if (raw) saved = JSON.parse(raw) as Partial<State>
  } catch { /* noop */ }
  const state = { ...DEFAULTS }
  for (const k of Object.keys(DEFAULTS) as StateKey[]) {
    const v = saved?.[k]
    if (typeof v === 'number' && Number.isFinite(v)) state[k] = v
  }
  return { wallpaper, state }
}

function persist(state: State): void {
  try { localStorage.setItem(STATE_KEY, JSON.stringify(state)) } catch { /* noop */ }
}

/* ------------------------------------------------------------------ */
/* Wallpaper upload compression (ported from the original plugin)       */
/* ------------------------------------------------------------------ */

/** Compress an uploaded wallpaper to a size the browser can load reliably. */
function compressWallpaper(img: HTMLImageElement): string {
  const SIZE_BUDGET = 1500000 // base64 chars, ~1.1MB binary
  const MIN_QUALITY = 0.45
  const fit = (maxSide: number) => {
    const scale = Math.min(1, maxSide / Math.max(img.width, img.height))
    return { w: Math.max(1, Math.round(img.width * scale)), h: Math.max(1, Math.round(img.height * scale)) }
  }
  const draw = (dims: { w: number; h: number }, q: number) => {
    const canvas = document.createElement('canvas')
    canvas.width = dims.w
    canvas.height = dims.h
    canvas.getContext('2d')?.drawImage(img, 0, 0, dims.w, dims.h)
    return canvas.toDataURL('image/jpeg', q)
  }
  const squeeze = (dims: { w: number; h: number }, q: number) => {
    let url = draw(dims, q)
    while (url.length > SIZE_BUDGET && q > MIN_QUALITY) {
      q = Math.max(MIN_QUALITY, q - 0.08)
      url = draw(dims, q)
    }
    return url
  }
  let dims = fit(2402)
  let dataUrl = squeeze(dims, 0.82)
  let shrink = 0
  while (dataUrl.length > SIZE_BUDGET && shrink < 3) {
    shrink += 1
    dims = fit(Math.round(2402 * Math.pow(0.78, shrink)))
    dataUrl = squeeze(dims, 0.72)
  }
  return dataUrl
}

/* ------------------------------------------------------------------ */
/* React surface                                                        */
/* ------------------------------------------------------------------ */

function SliderRow(props: {
  label: string
  value: number
  min: number
  max: number
  step?: number
  hint?: string
  onChange: (v: number) => void
  css: Record<string, string | undefined>
}): ReturnType<typeof createElement> {
  const { label, value, min, max, onChange, hint, css, step } = props
  return createElement('div', { className: css.sknRow },
    createElement('div', { className: css.sknRowHead },
      createElement('span', { className: css.sknRowLabel }, label),
      createElement('span', { className: css.sknRowValue }, `${value}%`),
    ),
    createElement('input', {
      type: 'range', min, max, step: step === undefined ? 1 : step, value,
      className: css.sknRange,
      onChange: (e: { target: { value: string } }) => onChange(Number(e.target.value)),
    }),
    hint === undefined ? null : createElement('div', { className: css.sknRowHint }, hint),
  )
}

/* ------------------------------------------------------------------ */
/* apply                                                                */
/* ------------------------------------------------------------------ */

/**
 * Apply the 时光代理人 skin: body attribute, theme-token remap, wallpaper
 * backdrop, control surface. All writes are retracted by the disposer.
 * @param ctx - owning context (the effect lifecycle owns retraction).
 */
export function apply(ctx: Context): void {
  const body = document.body
  const root = document.documentElement
  const { wallpaper, state } = loadInitial()
  const ui = { listeners: new Set<() => void>() }
  const bump = () => ui.listeners.forEach((fn) => fn())

  let themeRef: ThemeService | undefined = ctx.get('theme') as ThemeService | undefined

  const rgba = (r: number, g: number, b: number, a: number) => `rgba(${r}, ${g}, ${b}, ${a})`
  const near = (v: number, d: number) => Math.min(1, v + d)

  function applyThemeTokens(): void {
    if (themeRef === undefined || typeof themeRef.overrideTokens !== 'function') return
    /* 色板取自内嵌壁纸的实测主色：雾紫粉 #d6baca/#c9b7c5 × 石板蓝灰 #565a67/#373b46，
       点缀为画面高饱和的酒玫瑰 #963d55~#a44e71（陆光的粉外套 / 程小时的红围巾呼应）。 */
    themeRef.overrideTokens('link-click', {
      '--dsw-alias-bg-base': { light: rgba(246, 242, 247, state.bg / 100), dark: rgba(26, 24, 33, state.bg / 100) },
      '--dsw-alias-bg-layer-1': { light: rgba(250, 247, 251, state.layer1 / 100), dark: rgba(37, 34, 46, state.layer1 / 100) },
      '--dsw-alias-bg-layer-2': { light: rgba(252, 250, 253, near(state.layer1 / 100, 0.04)), dark: rgba(45, 41, 56, near(state.layer1 / 100, 0.03)) },
      '--dsw-alias-bg-overlay': { light: 'rgba(252, 249, 252, 0.97)', dark: 'rgba(33, 30, 41, 0.97)' },
      '--dsw-alias-border-l1': { light: 'rgba(152, 138, 164, 0.30)', dark: 'rgba(214, 186, 202, 0.12)' },
      '--dsw-alias-border-l2': { light: 'rgba(144, 126, 156, 0.42)', dark: 'rgba(214, 186, 202, 0.18)' },
      '--dsw-alias-brand-primary': { light: '#A34A62', dark: '#E8A0B5' },
      '--dsw-alias-label-primary': { light: '#2F2A38', dark: '#F1EDF5' },
      '--dsw-alias-label-secondary': { light: '#6B6273', dark: '#BDB4C6' },
      '--dsw-alias-state-error-primary': { light: '#B84455', dark: '#E57A8A' },
      '--dsw-alias-state-success-primary': { light: '#5E9B6E', dark: '#7CC08A' },
      '--dsw-alias-state-warn-primary': { light: '#C08A3E', dark: '#D9A65A' },
      '--dsw-specific-sidebar-fill': { light: rgba(250, 247, 251, state.sidebar / 100), dark: rgba(21, 19, 27, state.sidebar / 100) },
    })
  }

  function applyVars(): void {
    const w = state.wallpaper ? `url("${state.wallpaper}")` : `url(${WALLPAPER})`
    root.style.setProperty('--skn-bg-image', w)
    root.style.setProperty('--skn-zoom', `${state.zoom}%`)
    root.style.setProperty('--skn-pos-x', `${state.pos}%`)
    root.style.setProperty('--skn-genui-tint', `${state.genui}%`)
  }

  const commit = (key: StateKey) => (v: number) => {
    state[key] = v
    if (key === 'bg' || key === 'layer1' || key === 'sidebar') applyThemeTokens()
    if (key === 'pos' || key === 'zoom' || key === 'genui') applyVars()
    persist(state)
    bump()
  }

  const handleFile = (e: { target: HTMLInputElement & { files: FileList | null } }) => {
    const file = e.target.files && e.target.files[0]
    e.target.value = ''
    if (!file) return
    const reader = new FileReader()
    reader.onload = () => {
      const img = new Image()
      img.onload = () => {
        const dataUrl = compressWallpaper(img)
        try { localStorage.setItem(WALLPAPER_KEY, dataUrl) } catch { /* noop */ }
        state.wallpaper = dataUrl
        applyVars()
        bump()
      }
      img.src = String(reader.result)
    }
    reader.readAsDataURL(file)
  }

  const resetWallpaper = () => {
    try { localStorage.removeItem(WALLPAPER_KEY) } catch { /* noop */ }
    state.wallpaper = undefined
    applyVars()
    bump()
  }

  const resetAll = () => {
    for (const k of Object.keys(DEFAULTS) as StateKey[]) state[k] = DEFAULTS[k]
    try { localStorage.removeItem(WALLPAPER_KEY) } catch { /* noop */ }
    state.wallpaper = undefined
    persist(state)
    applyThemeTokens()
    applyVars()
    bump()
  }

  function useUI(): void {
    const [, force] = useState(0)
    useEffect(() => {
      ui.listeners.add(force)
      return () => { ui.listeners.delete(force) }
    }, [])
  }

  function SkinToggle(): ReturnType<typeof createElement> {
    return createElement('button', {
      className: 'skn-hbtn',
      title: 'Link Click 皮肤',
      onClick: () => {
        const layout = ctx.get('layout') as LayoutService | undefined
        if (layout !== undefined) layout.openDetails()
      },
    }, createElement('span', null, '🖌'))
  }

  function SkinPanel(): ReturnType<typeof createElement> {
    useUI()
    const css = {} as Record<string, string | undefined>
    return createElement('div', { className: 'skn-details' },
      createElement('div', { className: 'skn-details-head' },
        createElement('div', { className: 'skn-title-lg' }, 'Link Click 皮肤'),
        createElement('button', {
          className: 'skn-close', title: '关闭',
          onClick: () => {
            const layout = ctx.get('layout') as LayoutService | undefined
            if (layout !== undefined) layout.closeDetails()
          },
        }, '✕'),
      ),
      createElement('div', { className: 'skn-desc' }, '所有调节自动保存（含壁纸），刷新/重启后保持当前观感。'),
      createElement(SliderRow, { label: '主界面背景', value: state.bg, min: 35, max: 100, hint: '聊天区与面板的底色透明度，越低壁纸越清晰', onChange: commit('bg'), css }),
      createElement(SliderRow, { label: '卡片与消息', value: state.layer1, min: 35, max: 100, hint: '消息气泡、代码块等抬升面的透明度', onChange: commit('layer1'), css }),
      createElement(SliderRow, { label: '侧边栏', value: state.sidebar, min: 35, max: 100, hint: '左侧会话栏的透明度', onChange: commit('sidebar'), css }),
      createElement(SliderRow, { label: 'GenUI 卡片', value: state.genui, min: 20, max: 100, hint: '对话里 GenUI 面板的底色浓度，越高越实、越低越透', onChange: commit('genui'), css }),
      createElement('div', { className: 'skn-section' }, '壁纸'),
      createElement(SliderRow, { label: '水平位置', value: state.pos, min: 0, max: 100, hint: '0% 靠左，100% 靠右，50% 居中（放大后左右平移更明显）', onChange: commit('pos'), css }),
      createElement(SliderRow, { label: '图片大小', value: state.zoom, min: 60, max: 250, hint: '100% 为铺满高度；调大放大图片，调小显示更多', onChange: commit('zoom'), css }),
      createElement('div', { className: 'skn-file-row' },
        createElement('label', { className: 'skn-file-label' },
          '更换壁纸',
          createElement('input', { type: 'file', accept: 'image/*', className: 'skn-file', onChange: handleFile }),
        ),
        state.wallpaper ? createElement('button', { className: 'skn-mini', onClick: resetWallpaper }, '恢复默认壁纸') : null,
      ),
      createElement('div', { className: 'skn-row-hint' }, '上传的壁纸会自动压缩（约 ≤1.5MB，过大自动降质/缩小），避免存了但加载不出来。'),
      createElement('button', { className: 'skn-reset', onClick: resetAll }, '恢复全部默认'),
    )
  }

  /* body attribute + CSS variables first (the scoped stylesheet rides the
     CSS-modules auto-inject; variables are set from JS because the default
     wallpaper is a large inline data URI). */
  body.setAttribute('data-dsh-link-click', '')
  applyVars()

  ctx.effect(() => {
    const slots = ctx.get('slots') as SlotsService | undefined
    const disposers: Array<() => void> = []
    if (slots !== undefined && typeof slots.inject === 'function') {
      disposers.push(slots.inject('conversation.session.header.actions', () => slots.register(
        { name: 'conversation.session.header.actions', id: 'skin-toggle', order: 25, label: () => '皮肤' },
        () => createElement(SkinToggle, {}),
      )))
      disposers.push(slots.inject('details', () => slots.register(
        { name: 'details', priority: -1 },
        () => createElement(SkinPanel, {}),
      )))
    }
    return () => {
      for (const d of disposers) { try { d() } catch { /* noop */ } }
      body.removeAttribute('data-dsh-link-click')
      for (const prop of ['--skn-bg-image', '--skn-zoom', '--skn-pos-x', '--skn-genui-tint']) {
        root.style.removeProperty(prop)
      }
    }
  }, 'ui-skin-link-click: wallpaper + control surface')

  ctx.inject?.(['theme'], (themeCtx: { theme: ThemeService }) => {
    themeRef = themeCtx.theme
    applyThemeTokens()
  })
}
